// Reclamos del lote: CSV con comillas y comas en el texto. Se quita el BOM y se ordena por ingreso.
const p = $('CA85bP_Parametros').first().json;
const n = new Date(), z = (x) => String(x).padStart(2, '0');
const prefijo = `PRUEBA-${n.getFullYear()}${z(n.getMonth() + 1)}${z(n.getDate())}${z(n.getHours())}${z(n.getMinutes())}${z(n.getSeconds())}-`;
let txt = String($input.first().json.data || '').replace(/^﻿/, '');
const filas = []; let fila = [], campo = '', comillas = false;
for (let i = 0; i < txt.length; i++) {
  const ch = txt[i];
  if (comillas) {
    if (ch === '"' && txt[i + 1] === '"') { campo += '"'; i++; }
    else if (ch === '"') comillas = false;
    else campo += ch;
  } else if (ch === '"') comillas = true;
  else if (ch === ',') { fila.push(campo); campo = ''; }
  else if (ch === '\n' || ch === '\r') { if (ch === '\r' && txt[i + 1] === '\n') i++; fila.push(campo); filas.push(fila); fila = []; campo = ''; }
  else campo += ch;
}
if (campo !== '' || fila.length) { fila.push(campo); filas.push(fila); }
const cab = filas.shift().map((c) => c.trim());
let correos = filas.filter((f) => f.length === cab.length).map((f) => Object.fromEntries(cab.map((c, k) => [c, f[k]])));
correos.sort((a, b) => a.fecha_hora_ingreso.localeCompare(b.fecha_hora_ingreso) || a.reclamo_id.localeCompare(b.reclamo_id));
correos = correos.filter((c) => p.ids.includes(c.reclamo_id));
return correos.map((c) => ({ json: { ...c, prefijo_id: prefijo } }));

// Tres pasadas de seguimiento con hora simulada: justo antes del primer vencimiento, después del último y otra vez igual.
const d = $input.all().map((i) => i.json).filter((r) => r.vence_primera_respuesta);
const aDate = (s) => new Date(s.replace(' ', 'T') + ':00Z');
const aTexto = (t) => t.toISOString().slice(0, 16).replace('T', ' ');
const orden = [...d].sort((a, b) => a.vence_primera_respuesta.localeCompare(b.vence_primera_respuesta));
const prefijo = $('CA85bP_Ordenar').first().json.prefijo_id;
const t1 = aTexto(new Date(aDate(orden[0].vence_primera_respuesta).getTime() - 60000));
const t2 = aTexto(new Date(aDate(orden[orden.length - 1].vence_primera_respuesta).getTime() + 60000));
return [
  { json: { modo: 'seguimiento', ahora: t1, prefijo, paso: 'antes del primer vencimiento', primero: orden[0].reclamo_id } },
  { json: { modo: 'seguimiento', ahora: t2, prefijo, paso: 'después del último vencimiento' } },
  { json: { modo: 'seguimiento', ahora: t2, prefijo, paso: 'repetido: no debe duplicar' } },
];

const AREA = { 'RL-001': 'Atención al cliente', 'RL-002': 'Logística', 'RL-003': 'Logística', 'RL-005': 'Logística', 'RL-007': 'Atención al cliente', 'RL-008': 'Ventas', 'RL-034': 'Administración' };
const der = $('CA85bP_Derivar').all().map((i) => i.json);
const plan = $('CA85bP_Plan_seguimiento').all().map((i) => i.json);
const seg = $input.all().map((i) => i.json);
const base = (id) => String(id || '').replace(/^PRUEBA-\d+-/, '');
const casos = der.map((r) => ({ json: { caso: 'Derivar ' + base(r.reclamo_id), esperado: AREA[base(r.reclamo_id)],
  resultado: r.estado === 'derivado' && r.area === AREA[base(r.reclamo_id)] && r.vence_primera_respuesta < r.vence_resolucion ? 'PASA' : 'FALLA',
  detalle: JSON.stringify({ area: r.area, categoria: r.categoria, primera_respuesta_hasta: r.vence_primera_respuesta, resolucion_hasta: r.vence_resolucion }) } }));
const ids = (l) => (l || []).map((x) => base(x.reclamo_id));
const s1 = seg[0] || {}, s2 = seg[1] || {}, s3 = seg[2] || {};
casos.push({ json: { caso: 'Seguimiento ' + plan[0].ahora + ' (' + plan[0].paso + ')', esperado: 'Aviso a ' + base(plan[0].primero) + ' y ningún escalado',
  resultado: ids(s1.avisos).includes(base(plan[0].primero)) && ids(s1.escalados).length === 0 ? 'PASA' : 'FALLA', detalle: JSON.stringify({ avisos: ids(s1.avisos), escalados: ids(s1.escalados) }) } });
casos.push({ json: { caso: 'Seguimiento ' + plan[1].ahora + ' (' + plan[1].paso + ')', esperado: '7 escalados al Jefe de Atención',
  resultado: ids(s2.escalados).length === 7 ? 'PASA' : 'FALLA', detalle: JSON.stringify({ avisos: ids(s2.avisos), escalados: ids(s2.escalados) }) } });
casos.push({ json: { caso: 'Seguimiento ' + plan[2].ahora + ' (' + plan[2].paso + ')', esperado: 'Nada nuevo',
  resultado: ids(s3.avisos).length === 0 && ids(s3.escalados).length === 0 ? 'PASA' : 'FALLA', detalle: JSON.stringify({ avisos: ids(s3.avisos), escalados: ids(s3.escalados) }) } });
return casos;
